card.statement:
If $T(v)$ is a generic Gelfand-Tsetlin tableau of height $3$, then the vector space $V(T(v))$ spanned by the set of tableaux $\mathcal{B}(T(v))$ has a structure of a Gelfand-Tsetlin $\mathfrak{sl}(3)$-module with the action of $\mathfrak{sl}(3)$ on $V(T(v))$ given by the Gelfand-Tsetlin formulas:

\begin{eqnarray*}
E_{12}(T(w))=&  -(w_{21}-w_{11})(w_{22}-w_{11})T(w+\delta^{11}),\\
E_{21}(T(w))=&  T(w-\delta^{11}),\\
E_{32}(T(w))=&  \displaystyle\frac{w_{21}-w_{11}}{w_{21}-w_{22}}T(w-\delta^{21})-\frac{w_{22}-w_{11}}{w_{21}-w_{22}}T(w-\delta^{22}),\\
E_{23}(T(w))=& \displaystyle\frac{(w_{31}-w_{21})(w_{32}-w_{21})(w_{33}-w_{21})}{w_{21}-w_{22}}T(w+\delta^{21})\\
& -\displaystyle\frac{(w_{31}-w_{22})(w_{32}-w_{22})(w_{33}-w_{22})}{w_{21}-w_{22}}T(w+\delta^{22}).
\end{eqnarray*}

\begin{eqnarray*}
E_{13}(T(w))=& \displaystyle\frac{(w_{21}-w_{31})(w_{21}-w_{32})(w_{21}-w_{33})(w_{22}-w_{11})}{w_{21}-w_{22}}T(w+\delta^{21}+\delta^{11})\\
& +\displaystyle\frac{(w_{31}-w_{22})(w_{32}-w_{22})(w_{33}-w_{22})(w_{21}-w_{11})}{w_{21}-w_{22}}T(w+\delta^{22}+\delta^{11}),\\
E_{31}(T(w))=&\displaystyle\frac{1}{w_{21}-w_{22}}T(w-\delta^{21}-\delta^{11})-\frac{1}{w_{21}-w_{22}}T(w-\delta^{22}-\delta^{11}).
\end{eqnarray*}

\begin{eqnarray}
H_{1}(T(w))=& (2w_{11}-(w_{21}+w_{22}+1))T(w), \\
H_{2}(T(w))=& (2(w_{21}+w_{22}+1)-w_{11})T(w), \end{eqnarray}
